alzeme bileşimi ve montaj kapsamı da netleşmelidir. Doku seçimi bu kararların görsel tarafıdır."}') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.content (id,key,title,body) VALUES ('home-bestsellers','home-bestsellers','{"tr":"Ana sayfa · En çok satanlar","en":"Homepage · Bestsellers","ru":"Главная · Популярные товары"}','{"en":"","ru":"","tr":"{\"productIds\":[\"p1\",\"p2\",\"p3\"],\"intervalSeconds\":5,\"frames\":{}}"}') ON CONFLICT(id) DO NOTHING;
